import sys
from collections import deque

def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    T = int(input[idx])
    idx += 1
    results = []
    for _ in range(T):
        N = int(input[idx])
        idx += 1
        edges = []
        for _ in range(N - 1):
            u = int(input[idx])
            v = int(input[idx + 1])
            edges.append((u, v))
            idx += 2
        degrees = [0] * (N + 1)
        for u, v in edges:
            degrees[u] += 1
            degrees[v] += 1
        leaves = [i for i in range(1, N + 1) if degrees[i] == 1]
        if len(leaves) <= 2:
            results.append(0)
        else:
            queue = deque(leaves)
            while len(queue) > 2:
                leaf = queue.popleft()
                for u, v in edges:
                    if u == leaf:
                        neighbor = v
                    elif v == leaf:
                        neighbor = u
                    else:
                        continue
                    degrees[neighbor] -= 1
                    if degrees[neighbor] == 1:
                        queue.append(neighbor)
            results.append(len(leaves) - 2)
    for result in results:
        print(result)

main()
